mapper.select:
SELECT i.sku_id, i.spu_code_snapshot, i.product_name_snapshot, i.sku_code_snapshot, i.spec_name_snapshot, i.sale_unit_snapshot, count(*) AS line_count, count(DISTINCT i.sales_order_id) AS order_count, count(DISTINCT t.id) AS task_count, sum(i.planned_quantity_snapshot) AS planned_quantity, sum(i.sorted_quantity) AS sorted_quantity, sum(CASE WHEN i.result IS NULL THEN 1 ELSE 0 END) AS unprocessed_count FROM sorting_task_item i JOIN sorting_task t ON t.id=i.task_id AND t.deleted=FALSE WHERE i.deleted=FALSE AND i.occupation_status='ACTIVE' AND t.status=#{q.taskStatus} AND t.warehouse_id=#{q.warehouseId}
AND (i.product_name_snapshot ILIKE concat('%',#{q.keyword},'%') OR i.sku_code_snapshot ILIKE concat('%',#{q.keyword},'%') OR i.spu_code_snapshot ILIKE concat('%',#{q.keyword},'%'))
GROUP BY i.sku_id,i.spu_code_snapshot,i.product_name_snapshot,i.sku_code_snapshot,i.spec_name_snapshot, i.sale_unit_snapshot ORDER BY i.product_name_snapshot,i.sale_unit_snapshot,i.sku_code_snapshot

SELECT i.id AS sales_order_item_id, o.id AS sales_order_id, o.order_no, o.customer_id, o.customer_name_snapshot AS customer_name, i.spu_id, i.sku_id, i.spu_code_snapshot, i.product_name_snapshot, i.sku_code_snapshot, i.spec_name_snapshot, i.sale_unit_snapshot, i.product_type_snapshot, i.ordered_quantity, i.actual_quantity, o.confirmed_at, o.expect_delivery_time FROM sales_order o JOIN sales_order_item i ON i.order_id=o.id AND i.deleted=FALSE WHERE o.deleted=FALSE AND o.status='CONFIRMED' AND i.actual_quantity IS NOT NULL AND NOT EXISTS (SELECT 1 FROM sorting_task_item si WHERE si.sales_order_item_id=i.id AND si.deleted=FALSE AND si.occupation_status='ACTIVE') AND o.customer_id=#{q.customerId} AND o.id=#{q.orderId}
AND (o.order_no ILIKE concat('%',#{q.keyword},'%') OR o.customer_name_snapshot ILIKE concat('%',#{q.keyword},'%') OR i.product_name_snapshot ILIKE concat('%',#{q.keyword},'%'))
ORDER BY o.expect_delivery_time NULLS LAST,o.id DESC,i.sort_order,i.id

mapper.update:
UPDATE sorting_task
SET print_count=print_count + 1, last_printed_at=now(), last_printed_by=#{operator},
    updated_at=now(), updated_by=#{operator}
WHERE id = #{id}
  AND deleted = FALSE

UPDATE sorting_task_item
SET occupation_status='RELEASED', version=version + 1, updated_at=now(), updated_by=#{operator}
WHERE task_id = #{taskId}
  AND deleted = FALSE
  AND occupation_status = 'ACTIVE'
